mc(d,20,'LATS có lý do hạn chế trong môi trường không thể undo vì sao?','Tree search cần thử nhánh và quay lại trạng thái trước','LATS không bao giờ dùng tool','MCTS chỉ chấm final answer nên không cần môi trường','Search luôn có chi phí thấp hơn một agent đơn','Search layer cần môi trường cho phép undo và compute thêm; phù hợp hơn với task giá trị cao có thể rollback.','analyze')
mc(d,21,'Process reward model giúp khác outcome reward model ở thời điểm bắt lỗi nào?','Chấm từng bước để bắt lỗi trước khi lan sang bước sau','Chỉ chấm đáp án cuối sau toàn bộ trajectory','Chỉ chấm giá token thay chất lượng suy luận','Chỉ chọn model ban đầu rồi không quan sát quá trình','ORM đánh giá outcome cuối; PRM đánh giá các bước trung gian nên có thể phát hiện lỗi sớm.')
mc(d,26,'Skill file on-demand khác persistent instruction file ở thời điểm nạp nào?','Chỉ nạp kỹ năng chi tiết khi task liên quan, thay vì luôn nạp lúc khởi động','Luôn nạp mọi skill vào mọi request trước task','Chỉ nạp sau khi agent đã hoàn tất mọi hành động','Không bao giờ được đọc lại sau session đầu','Skill library cung cấp kiến thức domain theo yêu cầu; persistent instructions áp dụng thường trực từ lúc khởi động.')
mc(d,28,'Thay đổi nào thể hiện cải tiến sống qua ranh giới episode?','Skill đã xác minh được ghi ra library để task sau dùng lại','Chỉ một nhánh search bị bỏ khi chọn xong đáp án','Chỉ một reflection trong context rồi xóa khi task kết thúc','Chỉ tăng số lần retry trong cùng episode','Self-evolution đòi thay đổi còn tồn tại sau task; skill library là artifact ngoại vi được tái sử dụng.')
mc(d,31,'Một biến thể agent tăng điểm trên một benchmark nhưng phá các task cũ. Nó thiếu gate nào?','Regression set bảo toàn năng lực cũ','Chỉ kiểm source code có parse được','Chỉ so token count thấp hơn','Chỉ xem tác giả có tự đánh giá tốt hơn','Performance preservation yêu cầu năng lực cũ không bị phá; cần regression và kiểm transfer để phân biệt cải tiến với overfit.','apply')
mc(d,32,'Agent có quyền tự sửa source của chính nó. Guardrail/budget breaker nên đặt ở đâu?','Tầng infrastructure mà vòng tự cải tiến không có quyền ghi','Trong cùng vùng source agent được sửa tùy ý','Chỉ trong prompt nhắc agent đừng sửa luật','Trong reflection memory có thể bị ghi đè sau mỗi lượt','Safety boundary cần tách vùng tự sửa khỏi allowlist/capability/budget controls; nếu cùng vùng ghi, agent có thể sửa luôn guardrail.','apply')
mc(d,35,'Tách Plan–Act–Verify tạo lợi ích chẩn đoán nào?','Phân biệt mục tiêu sai, tool lỗi và không đạt tiêu chí kiểm chứng','Gộp mọi lỗi thành một transcript không phân pha','Luôn giảm số model call so với một loop','Loại bỏ nhu cầu dành budget riêng cho từng pha','Mỗi pha có prompt, budget và failure signal riêng; đổi thêm latency để dễ xác định pha gây lỗi.')
mc(d,37,'Plan file trên đĩa có ưu thế gì so với plan liên tục được viết lại trong context?','Có thể diff và còn nguyên qua compaction','Tự giải mọi subtask mà không cần cập nhật','Không cần schema/todo state vì chỉ là text','Bắt buộc viết lại toàn bộ file ở mỗi turn','Artifact ngoài context có địa chỉ, diff được và sống qua compaction; patch tiến độ tránh drift do viết lại toàn bộ.')
mc(d,43,'Một bước sắp gọi model cần chèn skill liên quan và trạng thái todo mới nhất. Hook nào phù hợp?','before_model','after_agent chỉ chạy cuối phiên','wrap_tool_call chỉ khi đã thực thi tool','before_agent chỉ chạy một lần rồi không nhìn state mới','before_model chạy trước mỗi model call sau khi state cập nhật, cho phép quyết định model sẽ thấy ngữ cảnh nào.','apply')
mc(d,44,'Critic đánh giá output vừa sinh và yêu cầu retry nên đặt ở hook nội dung nào?','after_model','before_agent chỉ để mở phiên','after_agent sau khi đã kết thúc toàn bộ','wrap_tool_call chỉ vì output là văn bản','after_model chấm nội dung output, ghi reflection và có thể từ chối chấp nhận để model thử lại.')
mc(d,45,'Một root trace span và budget cho cả lần chạy nên được mở/chốt ở cặp hook nào?','before_agent và after_agent','before_model và before_model lần kế tiếp','wrap_tool_call và một tool bất kỳ cuối','Chỉ after_model cho từng output riêng','before_agent khởi tạo hạn mức/root span, after_agent chốt tổng token/cost và kết quả phiên.')
mc(d,51,'Structured eviction có đánh đổi nào so với LLM compaction?','Rẻ và dự đoán được phần bị xóa, nhưng không tổng hợp ngữ nghĩa rải rác','Luôn giữ đầy đủ mọi ý nghĩa như summary hoàn hảo','Đòi thêm một LLM call để áp mỗi rule xóa','Chỉ đổi tên block mà không giảm context','Eviction xóa theo rule cố định không gọi model; compaction lossy nhưng tổng hợp semantic relevance, có chi phí riêng.')
mc(d,54,'Worker nên trả gì cho orchestrator để duy trì context isolation?','Bản tóm tắt kết quả cô đọng thay nguyên transcript','Toàn bộ transcript cùng mọi tool dump mặc định','Context của các worker khác để tự hòa giải','Chỉ một thông báo đã xong không có kết quả','Worker có context riêng và trả summary ngắn; dump transcript làm mất lợi ích giữ main context sạch.')
mc(d,64,'Nguồn được trích là thật nhưng đoạn nguồn không hỗ trợ claim thuộc lỗi nào?','Misattributed claim','Unsupported claim không có citation đi kèm','Fabricated source không tồn tại','Một citation đúng chỉ vì URL truy cập được','Xác minh source tồn tại chưa đủ; phải đối chiếu nội dung với claim để bắt misattribution.','apply')
