mc(d,5,'User đã nêu preference ở phiên trước nhưng phiên mới không nhận lại state nào. Vì sao model không tự nhớ?','API call độc lập không tự có persistent state giữa phiên','Trọng số model tự cập nhật mọi preference nhưng cần thêm turn','Chỉ cần tăng max_output_tokens để đọc được phiên cũ','Temperature thấp sẽ phục hồi lịch sử chưa được gửi','Persistence cần external store/retrieval; nội dung phiên trước không tự đi vào request mới.')
mc(d,8,'User preference mâu thuẫn policy constraint. Quy tắc ưu tiên nào phù hợp?','Policy thắng và cần được thiết kế rõ trong hệ thống','Preference mới nhất luôn ghi đè policy','Memory semantic gần query nhất được quyền bỏ policy','Cắt policy trước vì nó chiếm token','Policy context giữ ràng buộc an toàn; preference không thể tự cấp quyền vượt policy.','apply')
mc(d,12,'Sliding context kết hợp system, summary và K turn gần nhất nhằm cân bằng điều gì?','Giữ trạng thái tổng quát cùng chi tiết mới mà không mang toàn transcript','Giữ nguyên mọi turn vô hạn không tốn token','Loại toàn bộ summary và chỉ giữ final answer đầu tiên','Chỉ nạp long-term profile mà bỏ cuộc hội thoại hiện tại','Summary giữ phần cũ quan trọng, recent turns giữ chi tiết đang nóng; buffer toàn bộ dễ chạm limit.')
mc(d,13,'Redis Hash phù hợp lưu nhóm memory nào trong profile?','Preferences như ngôn ngữ và phong cách','Toàn bộ semantic vector index không metadata','Mỗi API response nguyên bản như một model weight','Một cây search chỉ tồn tại vài mili giây','Profile dùng Hash cho preference, Set cho facts và List cho lịch sử gần; TTL khác nhau theo loại.')
mc(d,16,'Memory router bắt đầu tác vụ cần đọc nhiều store rồi chèn theo priority. Lợi ích của một state interface là gì?','Tập hợp profile, episode và semantic hits trong ngân sách context có kiểm soát','Mặc định dump toàn bộ mọi store không trim','Bỏ mọi ưu tiên vì nhiều store đồng nghĩa context vô hạn','Chỉ lưu một chuỗi memory chung không provenance','State có các trường user_profile, episodes, semantic_hits và memory_budget, hỗ trợ load/inject có trật tự.')
mc(d,17,'Episodic memory lưu trajectory và outcome giúp tác vụ tương tự thế nào?','Biết hướng từng thất bại/thành công để chọn lại chiến lược','Chỉ nhớ một fact domain không liên quan kinh nghiệm','Luôn replay nguyên mọi action bất kể điều kiện mới','Thay thế hoàn toàn current task objective','Episode tuple gồm task, trajectory, outcome, reflection; dùng kinh nghiệm đã có khi tìm task tương tự.')
mc(d,19,'Unified retrieve(query) nên xử lý kết quả nhiều loại memory thế nào?','Merge context liên quan và trim theo token budget','Luôn trả toàn bộ store bất kể relevance','Chỉ lấy loại memory nhanh nhất rồi bỏ mọi loại khác','Tăng số kết quả vô hạn vì context retrieval không có phí','Một giao diện retrieval gộp bốn loại memory nhưng cần budget và priority để tránh context nhiễu.')
mc(d,21,'MVP cần nhanh nhưng đội production sau này cần toàn quyền logic memory đặc thù. Đánh đổi managed layer với custom Redis/Chroma là gì?','Managed setup nhanh hơn; custom chậm xây hơn nhưng kiểm soát đầy đủ','Custom luôn nhanh triển khai hơn vì không cần code','Managed luôn cho full control mọi policy nội bộ','Hai lựa chọn không có khác biệt vận hành','Framework API giúp go-to-market nhanh; custom cần xây từ đầu nhưng cho full control ở domain đặc thù.','analyze')
mc(d,22,'User yêu cầu xóa memory trong hệ nhiều agent có bản sao. Điều gì cần xảy ra?','Propagate xóa tới mọi agent/store liên quan và xác minh deletion','Chỉ xóa entry của agent nhận request đầu tiên','Chỉ đánh dấu hidden ở UI còn các copy vẫn dùng','Chỉ chờ TTL mọi bản sao tự hết mà không xử lý yêu cầu','Federated forgetting đòi xóa tất cả memory copy liên quan và confirm; deletion không dừng ở store chính.','apply')
mc(d,25,'Cross-session memory nên tổ chức scope chủ yếu theo hướng nào?','User/org scope cho facts bền, short-term vẫn theo thread','Mọi user dùng chung một namespace để tăng recall','Chỉ thread scope cho preference cần dùng nhiều phiên','Gộp raw transcript mọi thread vào một chuỗi không provenance','User-scoped structured facts/open loops duy trì liên tục, còn thread state tạm phục vụ phiên hiện tại.')
mc(d,26,'Memory record bền nên mang metadata nào để kiểm tra độ tin cậy và tuổi?','Source, timestamp, confidence và TTL','Chỉ nội dung fact không có nơi phát sinh','Chỉ tên model chung và bỏ thời điểm','Chỉ số thứ tự turn mà không user scope','Provenance và thời hạn giúp quản trị recall, expiry, conflict và isolation; gán nhầm user là lỗi nghiêm trọng.')
mc(d,27,'Sau compaction, context nên giữ ba lớp thông tin nào?','Recent turns, session summary và durable notes','Mọi raw transcript, mọi tool dump và mọi log đầy đủ','Chỉ final answer gần nhất không blockers/next steps','Chỉ long-term facts và bỏ toàn bộ trạng thái task','Ba lớp giữ chi tiết nóng, tóm tắt quyết định/blocker và facts/tasks đủ quan trọng để bền qua phiên.')
mc(d,28,'Khi nào nên kích hoạt compaction thay vì chạy liên tục mọi turn?','Gần token limit, session dài hoặc chuyển pha từ thảo luận sang thực thi','Chỉ sau khi request đã vượt hard context limit và fail','Mỗi token mới đều cần một full summary','Chỉ khi user tự gõ lệnh compact dù latency tăng','Compaction theo pressure/chuyển pha giúp tiết kiệm overhead; notes phải giữ decisions, TODO, constraints cụ thể.')
mc(d,29,'Instruction file như AGENTS.md còn thiếu khả năng gì của một retrieval engine?','Không tự re-rank, TTL, conflict resolution hay provenance','Tự tìm mọi preference liên quan bằng semantic ranking','Tự xóa memory hết hạn dù không có backend','Tự chứng minh mọi note là fact đã xác minh','Instruction files là control plane bootstrap hành vi; retrieval/governance memory vẫn cần cơ chế riêng.')
mc(d,30,'Vì sao kết hợp instruction files với structured memory backend?','Files định hướng cách cư xử; retrieval chọn điều cần nhớ lúc hiện tại','Files thay hết nhu cầu recall vì chứa mọi lịch sử','Memory backend tự đặt persona mà không policy','Hai hệ cùng giữ raw transcript vô hạn để chắc chắn nhớ','Instruction trả lời hành vi/default; backend recall theo scope/relevance cho preference, open loops, episode, knowledge.')
mc(d,31,'Heartbeat background pass có use case phù hợp nào?','Deduplicate notes, refresh backlog và expire task cũ','Tự nâng quyền để hoàn tất task bị policy chặn','Viết mọi instruction mới từ nội dung untrusted mà không kiểm','Gọi lại toàn bộ tool tác vụ cũ bất kể thay đổi state','Heartbeat duy trì state và backlog qua ngày, giảm áp lực làm mọi consolidation ở cuối chat.')
mc(d,32,'Một heartbeat định ghi preference nhạy cảm từ đoạn text bên ngoài. Kiểm soát nào cần trước durable write?','Policy/human check theo tác động và ghi provenance rõ','Coi mọi inference của agent như user instruction đã đồng ý','Cho heartbeat tự cấp quyền vì nó chạy nền','Bỏ source metadata để note ngắn hơn','Persistent injection có thể thành memory/backlog poisoning; allowlist loại ghi, provenance và review high-impact write là guardrail.','apply')
